<script lang="ts">
  // About Farba > Licenses: the third-party notices generated by scripts/gen-licenses.mjs
  // (`pnpm licenses`) into ui/public/licenses.json. A searchable list grouped by kind; a row
  // expands to the project's address and licence text (same as in Hyper, owner request).
  import { invoke } from "@tauri-apps/api/core";
  import Dialog from "./Dialog.svelte";
  import type { DialogProps } from "../../lib/dialogs.svelte";

  interface Pkg {
    kind: "origin" | "bundled" | "asset" | "rust" | "js";
    name: string;
    version: string;
    license: string;
    repository: string;
    note?: string;
    texts: string[];
  }
  interface Data {
    generated: string;
    packages: Pkg[];
    texts: Record<string, string>;
  }

  let { close }: DialogProps<void> = $props();

  let data = $state<Data | null>(null);
  let error = $state<string | null>(null);
  let query = $state("");
  let openKey = $state<string | null>(null);

  const GROUPS: { kind: Pkg["kind"]; label: string }[] = [
    { kind: "origin", label: "Based on" },
    { kind: "bundled", label: "Native libraries" },
    { kind: "asset", label: "Icons" },
    { kind: "rust", label: "Rust libraries" },
    { kind: "js", label: "JavaScript libraries" },
  ];

  const filtered = $derived.by(() => {
    const q = query.trim().toLowerCase();
    const list = data?.packages ?? [];
    return q
      ? list.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q))
      : list;
  });
  const summary = $derived.by(() => {
    const counts = new Map<string, number>();
    for (const p of data?.packages ?? []) counts.set(p.license, (counts.get(p.license) ?? 0) + 1);
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
  });

  fetch("/licenses.json")
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
    .then((d: Data) => (data = d))
    .catch((e) => (error = String(e)));

  const key = (p: Pkg) => `${p.kind}:${p.name}@${p.version}`;
</script>

<Dialog title="Open-source licenses" width={720} onsubmit={() => close()} oncancel={() => close()}>
  <p class="dim">
    Farba is free software under GPL-3.0 and is built on the work of these projects.
    {#if data}· {data.packages.length} components{/if}
  </p>
  {#if data}
    <input
      type="search"
      placeholder="Search by name or license"
      bind:value={query}
      onkeydown={(e) => {
        // Enter would submit the dialog's form (= Close).
        if (e.key === "Enter") e.preventDefault();
      }}
    />
    <div class="chips">
      {#each summary as [lic, n] (lic)}
        <button
          type="button"
          class="chip"
          class:on={query === lic}
          onclick={() => (query = query === lic ? "" : lic)}>{lic} · {n}</button
        >
      {/each}
    </div>
    <div class="list">
      {#each GROUPS as g (g.kind)}
        {@const items = filtered.filter((p) => p.kind === g.kind)}
        {#if items.length}
          <h3>{g.label} <span class="dim">({items.length})</span></h3>
          {#each items as p (key(p))}
            {@const k = key(p)}
            <div class="item" class:open={openKey === k}>
              <button
                type="button"
                class="row"
                aria-expanded={openKey === k}
                onclick={() => (openKey = openKey === k ? null : k)}
              >
                <span class="name"
                  >{p.name}{#if p.version}<span class="ver">{p.version}</span>{/if}</span
                >
                <span class="lic" title={p.license}>{p.license}</span>
              </button>
              {#if openKey === k}
                <div class="body">
                  {#if p.note}<p class="note">{p.note}</p>{/if}
                  <button
                    type="button"
                    class="link"
                    onclick={() => void invoke("open_url", { url: p.repository })}
                    >{p.repository}</button
                  >
                  {#each p.texts as id (id)}
                    <pre>{data.texts[id]}</pre>
                  {/each}
                </div>
              {/if}
            </div>
          {/each}
        {/if}
      {/each}
    </div>
  {:else if error}
    <p class="dim">{error}</p>
  {:else}
    <p class="dim">…</p>
  {/if}
  {#snippet buttons()}
    <button type="submit" class="primary">Close</button>
  {/snippet}
</Dialog>

